import{_ as a,o as e,c as r,ae as i}from"./chunks/framework.BajMXG5H.js";const m=JSON.parse('{"title":"スマートキューシステム","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/smart-cue-system.md","filePath":"ja/guide/smart-cue-system.md"}'),o={name:"ja/guide/smart-cue-system.md"};function l(s,t,d,n,h,u){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="スマートキューシステム" tabindex="-1">スマートキューシステム <a class="header-anchor" href="#スマートキューシステム" aria-label="Permalink to &quot;スマートキューシステム&quot;">​</a></h1><p>キューシステムはOrchestraの通知メカニズムです。セッションがあなたの注意を必要とした時、ダッシュボード上部にキューが表示されます。</p><h2 id="キューのトリガー" tabindex="-1">キューのトリガー <a class="header-anchor" href="#キューのトリガー" aria-label="Permalink to &quot;キューのトリガー&quot;">​</a></h2><table tabindex="0"><thead><tr><th>トリガー</th><th>キュータイプ</th><th>説明</th></tr></thead><tbody><tr><td>Claudeが応答停止</td><td>WAITING_INPUT</td><td>続行するにはユーザーの入力が必要</td></tr><tr><td>権限要求</td><td>WAITING_PERMISSION</td><td>ツール使用の承認が必要</td></tr><tr><td>セッションエラー</td><td>ERROR</td><td>エラーが発生</td></tr><tr><td>ステイルセッション</td><td>WAITING_INPUT</td><td>設定されたタイムアウト期間中にアクティビティなし</td></tr></tbody></table><h2 id="キューレーン" tabindex="-1">キューレーン <a class="header-anchor" href="#キューレーン" aria-label="Permalink to &quot;キューレーン&quot;">​</a></h2><p>キューはダッシュボード上部の専用レーンに表示されます。各キューには以下が表示されます:</p><ul><li><strong>セッション名</strong> — どのセッションが注意を必要としているか</li><li><strong>理由</strong> — キューが作成された理由</li><li><strong>説明</strong> — コンテキストのための最終ログメッセージ</li><li><strong>Jumpボタン</strong> — セッションに直接移動</li><li><strong>Dismissボタン</strong> — ジャンプせずにキューを削除</li></ul><p>キューレーンはViewメニューからオン/オフを切り替えできます。</p><h2 id="キューのアクション" tabindex="-1">キューのアクション <a class="header-anchor" href="#キューのアクション" aria-label="Permalink to &quot;キューのアクション&quot;">​</a></h2><p>各キューは複数のアクションに対応しています:</p><ul><li><strong>Jump</strong> — セッションのターミナルウィンドウにナビゲート</li><li><strong>Snooze</strong> — セッションをグリッドから一時的に非表示（次のアクティビティで再表示）</li><li><strong>Hide</strong> — 次のアクティビティまでグリッドからセッションを削除</li><li><strong>Remove</strong> — セッションとキューを永久に削除</li></ul><h2 id="自動解決" tabindex="-1">自動解決 <a class="header-anchor" href="#自動解決" aria-label="Permalink to &quot;自動解決&quot;">​</a></h2><p>以下の場合、キューは自動的に解決されます:</p><ul><li>セッションが再び実行を開始した時（新しいツール使用を検出）</li><li>セッションが終了した時</li><li>手動でキューをDismissした時</li></ul><h2 id="サウンド通知" tabindex="-1">サウンド通知 <a class="header-anchor" href="#サウンド通知" aria-label="Permalink to &quot;サウンド通知&quot;">​</a></h2><p>新しいキューが表示された時、Orchestraはシステムサウンド（Glass）を再生してアラートします。アプリがバックグラウンドにある時も動作します。サウンド通知はViewメニューからオン/オフを切り替えできます。</p><h2 id="ステイルセッション検出" tabindex="-1">ステイルセッション検出 <a class="header-anchor" href="#ステイルセッション検出" aria-label="Permalink to &quot;ステイルセッション検出&quot;">​</a></h2><p>実行中のセッションが設定可能なタイムアウト期間中にhookイベントを受信しなかった場合、Orchestraは自動的にWAITING_INPUTキューを作成します。これはClaude Codeが停止したがStopフックが発火しなかったケースをカバーします。</p>',18)])])}const p=a(o,[["render",l]]);export{m as __pageData,p as default};
